function money(value: number | null) { return formatPrice(value) }
function getBook(id?: string) { return books.find((book) => book.id === id) || books[0] }
function safe(value: string | number | null | undefined) { return value === null || value === undefined || value === '' ? 'Information unavailable' : value }
function discount(book: Book) { return book.price && book.mrp ? Math.round((1 - book.price / book.mrp) * 100) : null }
function slug(value: string) { return value.toLowerCase().replace(/[^a-z0-9]+/g, '-') }

function Brand({ light = false }: { light?: boolean }) {
  return <span className="wordmark" style={light ? { color: 'var(--ink)' } : undefined}><span className="book-mark"><span /></span>MARKETHUB</span>
}

function Button({ children, to, onClick, variant = 'primary', type = 'button', className = '', disabled = false }: { children: ReactNode; to?: string; onClick?: () => void; variant?: 'primary' | 'secondary' | 'ghost' | 'dark' | 'text'; type?: 'button' | 'submit'; className?: string; disabled?: boolean }) {
  const classes = `button button-${variant} ${className}`
  return to ? <Link className={classes} to={to}>{children}</Link> : <button className={classes} type={type} onClick={onClick} disabled={disabled}>{children}</button>
}

function Chapter({ children }: { children: ReactNode }) { return <div className="chapter-label">{children}</div> }
function Rating({ book }: { book: Book }) { return <span className="rating"><Star size={12} fill="currentColor" /> {safe(book.rating)} <span>({safe(book.reviews)})</span></span> }
function Status({ children, tone = 'normal' }: { children: ReactNode; tone?: 'normal' | 'pending' | 'danger' }) { return <span className={`status-chip ${tone === 'pending' ? 'pending' : tone === 'danger' ? 'danger' : ''}`}>{children}</span> }

function BookPassport({ book }: { book: Book }) {
  const profile = getSellerProfile(book.vendor)
  const history = getBookPriceHistory(book)
  const offers = sellerOffers[book.id] || []
  return <section className="passport-panel">
    <div className="panel-heading"><div><Chapter>Book Passport</Chapter><h2 style={{ marginTop: 12 }}>A clearer view of this copy.</h2></div><ShieldCheck size={23} color="var(--gold)" /></div>
    <div className="passport-seller"><div><span className="micro-label">Listed by</span><Link to={`/vendors/${slug(book.vendor)}`}><strong>{book.vendor}</strong></Link></div>{profile?.verified && <span className="verified-label"><BadgeCheck size={14} /> Verified bookseller</span>}</div>
    <div className="passport-status"><span><Check size={14} /> Authenticity: publisher-sourced listing</span><span><BookOpen size={14} /> Condition: new {book.format ? `· ${book.format}` : ''}</span>{profile && <span><Truck size={14} /> Delivery estimate: {profile.deliveryDays}–{profile.deliveryDays + 2} days</span>}</div>
    <div className="passport-history"><div className="panel-heading"><h3>Price history</h3><span className="muted">Local mock · recent months</span></div>{history.length ? <div className="passport-chart"><ResponsiveContainer width="100%" height={110}><LineChart data={history}><XAxis dataKey="date" hide /><Tooltip formatter={(value) => [money(Number(value)), 'Price']} contentStyle={{ background: 'var(--ink-2)', border: '1px solid var(--line)', color: 'var(--paper)' }} /><Line type="monotone" dataKey="price" stroke="var(--gold)" strokeWidth={2} dot={false} /></LineChart></ResponsiveContainer></div> : <p className="muted">Price history is not available for this title.</p>}</div>
    {offers.length > 0 && <div className="passport-offers"><h3>Other sellers</h3>{offers.map((offer) => <div className="passport-offer" key={offer.vendor}><div><Link to={`/vendors/${slug(offer.vendor)}`}>{offer.vendor}</Link><span>{offer.condition}</span></div><div><strong>{money(offer.price)}</strong><small>{offer.deliveryDays}–{offer.deliveryDays + 2} days</small></div></div>)}</div>}
  </section>
}

function SellerPassport({ name }: { name: string }) {
  const profile = getSellerProfile(name)
  if (!profile) return <div className="empty-state"><h2>Seller details unavailable.</h2><p>This bookseller does not have a local passport record yet.</p></div>
  const score = getSellerScore(profile)
  const metrics = [
    ['Books sold', profile.booksSold.toLocaleString('en-IN')],
    ['Authenticity', `${profile.authenticityPct}%`],
    ['On-time delivery', `${profile.onTimeDeliveryPct}%`],
    ['Return rate', `${profile.returnRatePct}%`],
    ['Dispute rate', `${profile.disputeRatePct}%`],
    ['Active since', profile.activeSince]
  ]
  return <section className="seller-passport">
    <div className="seller-score-card"><div><span className="micro-label">Seller Passport</span><h2>{name}</h2><span className="verified-label"><BadgeCheck size={14} /> Verified bookseller</span></div><div className="seller-score"><strong>{score}</strong><span>Seller Score / 100</span></div></div>
    <div className="seller-metrics">{metrics.map(([label, value]) => <div className="seller-metric" key={label}><span>{label}</span><strong>{value}</strong></div>)}</div>
    <p className="seller-score-note">Score is calculated from authenticity (30%), on-time delivery (25%), returns (15%), disputes (15%), books sold (10%), and tenure (5%). <MapPin size={12} /> {profile.city}</p>
  </section>
}

function RankingDisclosure({ book, query }: { book: Book; query: string }) {
  const factors = getRankingFactors(book, query)
  const score = getOverallRankingScore(book, query)
  return <details className="ranking-disclosure"><summary>Why this result? <span>{score}/100</span></summary><div className="ranking-breakdown">{rankingWeights.map(({ key, label, weight }) => <div key={key}><span>{label} <small>{weight}%</small></span><strong>{factors[key]}/100</strong></div>)}<p>Overall score is the weighted total of these factors.</p></div></details>
}

function SellerRankingDisclosure({ name }: { name: string }) {
  const profile = getSellerProfile(name)
  if (!profile) return null
  return <details className="ranking-disclosure seller-ranking-disclosure"><summary>Why this seller? <span>{getSellerScore(profile)}/100</span></summary><div className="ranking-breakdown"><p>Score formula: authenticity 30%, on-time delivery 25%, returns 15%, disputes 15%, books sold 10%, and tenure 5%.</p><div><span>Verified</span><strong>{profile.verified ? 'Yes' : 'No'}</strong></div><div><span>Authenticity</span><strong>{profile.authenticityPct}%</strong></div><div><span>On-time delivery</span><strong>{profile.onTimeDeliveryPct}%</strong></div></div></details>
}

function BuyingPriorityFilter({ value, onChange }: { value: BuyingPriority | ''; onChange: (value: BuyingPriority | '') => void }) {
  return <label className="priority-filter"><span>What matters most?</span><select value={value} onChange={(event) => onChange(event.target.value as BuyingPriority | '')}><option value="">Standard shelf order</option>{buyingPriorities.map((priority) => <option key={priority} value={priority}>{priority}</option>)}</select><small>{value === 'Local Seller' ? 'Local seller priority uses Pune as the mock reference city.' : value === 'Best Return Policy' ? 'Ranks sellers by their stated mock return window.' : 'Sort locally by the priority you choose.'}</small></label>
}

function BookLifecycleStrip({ status = 'Shipped' }: { status?: string }) {
  const delivered = status === 'Delivered'
  const stages = ['Discover', 'Compare', 'Buy', 'Deliver', 'Review', 'Resell / Donate']
  const activeIndex = status === 'Pending' ? 2 : delivered ? 4 : 3
  return <section className="lifecycle-panel"><div><Chapter>Product lifecycle</Chapter><p>Books can begin another chapter after they reach your shelf.</p></div><ol className="lifecycle-strip">{stages.map((stage, index) => <li className={index < activeIndex ? 'complete' : index === activeIndex ? 'current' : ''} key={stage}><span>{index < activeIndex ? <Check size={12} /> : index + 1}</span><strong>{stage}</strong></li>)}</ol></section>
}

function MarketShieldNotice() {
  return <section className="marketshield-notice"><div className="marketshield-heading"><ShieldCheck size={20} color="var(--gold)" /><div><strong>MarketShield · demo checkout checks</strong><span>Visible security cues from the MarketHub security specification</span></div><Status>Local demo</Status></div><div className="marketshield-checks"><span><Check size={13} /> Prices come from the local catalogue</span><span><Check size={13} /> No real payment details are collected</span><span><Check size={13} /> No live order or shipment is created</span></div><p>The security specification also calls for server-side authorization, validated checkout rules, rate limiting, secure sessions, and audit logging. Those backend controls are not active in this mock UI.</p></section>
}

function CoverArt({ book, className = '', showTitle = true }: { book: Book; className?: string; showTitle?: boolean }) {
  const [broken, setBroken] = useState(false)
  const [loaded, setLoaded] = useState(false)
  return <div className={`cover-shell ${loaded || broken ? 'is-loaded' : 'is-loading'} ${className}`}>
    {book.cover && !broken ? <img src={book.cover} alt={`${book.title} cover`} loading="lazy" onLoad={() => setLoaded(true)} onError={() => { setBroken(true); setLoaded(false) }} /> : <div className="cover-fallback"><span>{book.category}</span><strong>{book.title}</strong></div>}
    <div className="cover-overlay" />
    {showTitle && <div className="cover-text">{book.title}</div>}
  </div>
}

