function Footer() {
  return <footer className="site-footer"><div className="container"><div className="footer-grid"><div className="footer-brand"><Brand /><p>A trusted multi-vendor bookstore for readers who want the next title to feel discovered, not merely listed.</p><Button to="/books" variant="ghost">Explore the catalogue <ArrowRight size={14} /></Button></div><div className="footer-col"><h4>Shop</h4><Link to="/books">Books</Link><Link to="/bestsellers">Bestsellers</Link><Link to="/category/fiction">Categories</Link><Link to="/authors">Authors</Link></div><div className="footer-col"><h4>Sell with us</h4><Link to="/vendor/register">Become a Vendor</Link><Link to="/vendor">Vendor Login</Link><Link to="/vendor/analytics">Vendor Analytics</Link></div><div className="footer-col"><h4>Help</h4><Link to="/customer/orders">Orders</Link><Link to="/customer/profile">Shipping</Link><Link to="/customer/profile">Returns</Link><Link to="/customer/profile">Contact</Link></div></div><div className="footer-bottom"><span>© 2026 MarketHub</span><span>Built for the curious.</span></div></div></footer>
}

function ToastStack() {
  const { toasts, dismissToast } = useMarket()
  return <div className="toast-stack" aria-live="polite">{toasts.map((toast) => <div className="toast" key={toast.id}><Check size={15} color="var(--success)" />{toast.message}<button className="icon-button" aria-label="Dismiss" onClick={() => dismissToast(toast.id)}><X size={13} /></button></div>)}</div>
}

function Assistant() {
  const [open, setOpen] = useState(false)
  const [input, setInput] = useState('')
  const [isThinking, setIsThinking] = useState(false)
  const [messages, setMessages] = useState<{ role: 'user' | 'assistant'; text: string; links?: { title: string; to: string }[]; why?: string[] }[]>([{ role: 'assistant', text: 'Tell me what you want to read. I can search the local MarketHub catalogue.' }])
  const respond = (raw: string) => {
    const prompt = raw.trim()
    if (!prompt) return
    setIsThinking(true)
    setMessages((current) => [...current, { role: 'user', text: prompt }])
    setInput('')
    const lower = prompt.toLowerCase()
    let matches = books.filter((book) => book.bestseller)
    if (lower.includes('mystery') || lower.includes('thriller')) matches = books.filter((book) => book.category.includes('Mystery'))
    else if (lower.includes('fantasy')) matches = books.filter((book) => book.category === 'Fantasy')
    else if (lower.includes('amish')) matches = books.filter((book) => book.author.toLowerCase().includes('amish'))
    else if (lower.includes('under') || lower.includes('₹500') || lower.includes('500')) matches = books.filter((book) => book.price !== null && book.price < 500)
    else if (lower.includes('compare')) matches = [...books].filter((book) => book.price !== null).sort((a, b) => (a.price || 0) - (b.price || 0))
    if (!matches.length) matches = [...books].sort((a, b) => getOverallRankingScore(b, prompt) - getOverallRankingScore(a, prompt))
    const recommendations = matches.slice(0, lower.includes('compare') ? 2 : 3)
    const text = `A few local-catalogue picks: ${recommendations.map((book) => book.title).join(', ')}.`
    const featured = recommendations[0]
    const seller = featured ? getSellerProfile(featured.vendor) : undefined
    const why = featured ? [
      `Genre match: ${featured.category}${lower.includes('fantasy') || lower.includes('mystery') ? ' fits your request' : ''}.`,
      `Price fit: ${featured.price === null ? 'price unavailable' : money(featured.price)}${lower.includes('500') && (featured.price || 0) < 500 ? ' is under ₹500' : ''}.`,
      `Seller trust: ${seller ? `${getSellerScore(seller)}/100 score` : 'seller score unavailable'}.`,
      `Reader rating: ${featured.rating === null ? 'not yet rated' : `${featured.rating}/5`}.`
    ] : []
    const links = recommendations.map((book) => ({ title: book.title, to: `/books/${book.id}` }))
    window.setTimeout(() => {
      setMessages((current) => [...current, { role: 'assistant', text, links, why }])
      setIsThinking(false)
    }, 550)
  }
  return <div className="assistant">{open && <div className="assistant-panel"><div className="assistant-head"><strong>Book assistant</strong><button className="icon-button" aria-label="Close assistant" onClick={() => setOpen(false)}><X size={15} /></button></div><div className="assistant-body" aria-live="polite">{messages.map((message, index) => <div key={index} className={`assistant-message ${message.role === 'user' ? 'user' : ''}`}><p>{message.text}</p>{message.links?.map((link) => <div key={link.to} style={{ marginTop: 6 }}><Link to={link.to} onClick={() => setOpen(false)} className="button-text">{link.title} <ArrowRight size={12} /></Link></div>)}{message.why && message.why.length > 0 && <div className="assistant-why"><strong>Why these picks?</strong><ul>{message.why.map((factor) => <li key={factor}>{factor}</li>)}</ul></div>}</div>)}{isThinking && <div className="assistant-thinking"><span className="loading-orbit" />Finding your next chapter…</div>}</div><div className="assistant-suggestions"><button disabled={isThinking} onClick={() => respond('Find me a mystery book')}>Mystery</button><button disabled={isThinking} onClick={() => respond('Recommend a fantasy book')}>Fantasy</button><button disabled={isThinking} onClick={() => respond('Show books under ₹500')}>Under ₹500</button></div><form className="assistant-form" onSubmit={(event) => { event.preventDefault(); respond(input) }}><input aria-label="Ask the book assistant" value={input} onChange={(event) => setInput(event.target.value)} placeholder="Ask about a book…" disabled={isThinking} /><button aria-label="Send prompt" type="submit" disabled={isThinking || !input.trim()}><Send size={14} /></button></form></div>}<button className={`assistant-toggle ${open ? 'is-open' : ''}`} aria-label={open ? 'Close book assistant' : 'Open book assistant'} aria-expanded={open} onClick={() => setOpen((value) => !value)}><Sparkles size={20} /></button></div>
}

function Layout({ children, noFooter = false }: { children: ReactNode; noFooter?: boolean }) {
  const location = useLocation()
  const { id = '' } = useParams()
  const order = orderRows.find((item) => item.id === id)
  const productBook = /^\/books\/[^/]+$/.test(location.pathname) ? books.find((book) => book.id === id) : undefined
  const showLifecycle = /^\/customer\/orders\/[^/]+$/.test(location.pathname)
  const showMarketShield = location.pathname === '/customer/checkout'
  return <div className="app"><Header /><main key={location.pathname} className="app-main route-enter">{children}</main>{productBook && <section className="container passport-slot"><BookPassport book={productBook} /></section>}{showLifecycle && <section className="container lifecycle-slot"><BookLifecycleStrip status={order?.status || 'Shipped'} /></section>}{showMarketShield && <section className="container marketshield-slot"><MarketShieldNotice /></section>}{!noFooter && <Footer />}<Assistant /><ToastStack /></div>
}

function BookCard({ book, query = '', showRanking = false }: { book: Book; query?: string; showRanking?: boolean }) {
  const { wishlist, toggleWishlist, addToCart } = useMarket()
  const isWishlisted = wishlist.includes(book.id)
  return <article className="book-card"><Link to={`/books/${book.id}`} aria-label={`View ${book.title}`}><CoverArt book={book} /></Link><div className="book-card-actions"><button className="icon-button" aria-label={isWishlisted ? 'Remove from wishlist' : 'Add to wishlist'} onClick={() => toggleWishlist(book.id)}><Heart size={15} fill={isWishlisted ? 'currentColor' : 'none'} color={isWishlisted ? 'var(--gold)' : undefined} /></button><button className="icon-button" aria-label="Add to cart" onClick={() => addToCart(book.id)}><ShoppingBag size={15} /></button></div><div className="book-card-body"><Link to={`/books/${book.id}`} className="book-card-title">{book.title}</Link><span className="book-card-author">{book.author}</span><div className="meta-row"><Rating book={book} /><span className={`stock ${book.stock === 0 || book.stock === null ? 'out' : ''}`}>{book.stock === null ? 'Stock unavailable' : book.stock === 0 ? 'Out of stock' : `${book.stock} in stock`}</span></div><div className="book-card-price-row"><span className="price">{money(book.price)}</span>{book.mrp && <span className="mrp">{money(book.mrp)}</span>}{discount(book) && <span className="discount">{discount(book)}% off</span>}</div>{showRanking && <RankingDisclosure book={book} query={query} />}</div></article>
}

function BookGrid({ items }: { items: Book[] }) {
  const location = useLocation()
  const [params] = useSearchParams()
  const { category = '' } = useParams()
  const query = params.get('q') || category.replace(/-/g, ' ')
  const isRecommendedPath = location.pathname === '/search' || location.pathname.startsWith('/category/')
  const [priority, setPriority] = useState<BuyingPriority | ''>(isRecommendedPath ? 'Best Overall Value' : '')
  const showPriority = location.pathname === '/books' || location.pathname === '/search' || location.pathname.startsWith('/category/')
  const sorted = priority ? sortBooksForPriority(items, priority, query) : items
  return <div className="book-grid-area">{showPriority && <BuyingPriorityFilter value={priority} onChange={setPriority} />}{sorted.length ? <div className="book-grid">{sorted.map((book) => <BookCard key={book.id} book={book} query={query} showRanking={isRecommendedPath || Boolean(priority)} />)}</div> : <div className="empty-state"><h2>No books found.</h2><p>Try a different chapter, author, or category. The shelf is always changing.</p><Button to="/books" variant="primary">Reset the shelf</Button></div>}</div>
}

function PageHero({ label, title, children }: { label: string; title: string; children?: ReactNode }) { return <section className="page-hero"><div className="container"><Chapter>{label}</Chapter><h1>{title}</h1>{children}</div></section> }

function HomePage() {
  const featured = books.find((book) => book.featured) || books[0]
  return <Layout><section className="hero"><div className="container hero-content"><Chapter>MarketHub / Secure multi-vendor bookstore</Chapter><h1>Discover your next chapter.</h1><p className="hero-copy">Explore books from trusted vendors, publishers and booksellers — all in one secure marketplace.</p><div className="btn-row" style={{ marginTop: 28 }}><Button to="/books" variant="primary">Explore Books <ArrowRight size={15} /></Button><Button to="/vendor/register" variant="ghost">Become a Vendor</Button></div><div className="hero-stats"><div className="hero-stat"><strong>55+</strong><span>Curated titles</span></div><div className="hero-stat"><strong>12</strong><span>Categories</span></div><div className="hero-stat"><strong>18</strong><span>Trusted vendors</span></div></div></div><div className="hero-side-note">A marketplace for readers</div></section><section className="section section-dark"><div className="container feature-spread"><div className="feature-copy"><Chapter>Featured / A title to begin with</Chapter><h2>{featured.title}</h2><p>{featured.description}</p><div className="feature-meta"><div><strong>{featured.author}</strong><span>Author</span></div><div><strong>{money(featured.price)}</strong><span>Member price</span></div></div><Button to={`/books/${featured.id}`} variant="secondary">Open the book <ArrowRight size={15} /></Button></div><div className="feature-visual"><div className="feature-cover-back" /><div className="feature-cover-back two" /><div className="feature-cover"><img src={FEATURED_IMAGE} alt="Editorial still life of a featured book" /><span aria-hidden="true" /></div></div></div></section><section className="category-band"><div className="container"><div className="section-heading"><div><Chapter>Browse by mood</Chapter><h2>Find the shelf<br />that feels like you.</h2></div><p>From first editions to late-night page turners, find a category that makes room for curiosity.</p></div><div className="category-grid">{categories.slice(0, 8).map((category, index) => <Link className="category-card" key={category} to={`/category/${slug(category)}`}><small>0{index + 1}</small><strong>{category}</strong><ArrowUpRight /></Link>)}</div></div></section><section className="editorial-band"><div className="container editorial-grid"><div><Chapter>For the repeat reader</Chapter><h2>Books worth turning the page for.</h2><p>Our bestseller shelf is not a list. It is a living spread of titles readers choose again and again — with the context to help you choose your next one.</p><div className="editorial-stat"><strong>4.8 / 5</strong><span>Average reader rating</span></div><Button to="/bestsellers" variant="primary">Enter the bestseller shelf <ArrowRight size={15} /></Button></div><div className="editorial-side"><div className="section-rule" /><p className="muted" style={{ fontSize: 12, lineHeight: 1.8, marginTop: 22 }}>A quieter, more considered way to shop. Every title has a vendor, a story, and a place in the wider reading life.</p><div style={{ marginTop: 55 }}><Button to="/vendors" variant="ghost">Meet the booksellers <Store size={14} /></Button></div></div></div></section></Layout>
}

function BestsellersPage() {
  const { addToCart } = useMarket()
  const [selectedId, setSelectedId] = useState((books.find((book) => book.bestseller) || books[0]).id)
  const selected = getBook(selectedId)
  const bestsellers = books.filter((book) => book.bestseller).slice(0, 5)
  return <Layout><div className="bestseller-page"><section className="bestseller-intro"><div className="container"><Chapter>MarketHub / Bestsellers</Chapter><h1>Books worth turning the page for.</h1><p>Discover the titles readers are choosing again and again — a living editorial shelf, not just another product grid.</p></div></section><section className="bestseller-showcase"><div className="container bestseller-showcase-inner"><div className="bestseller-copy"><span className="book-author">{selected.author}</span><h2 key={selected.id}>{selected.title}</h2><p>{selected.description}</p><div className="bestseller-info"><div className="bestseller-info-item"><strong><Rating book={selected} /></strong><span>Reader signal</span></div><div className="bestseller-info-item"><strong>{money(selected.price)}</strong><span>Price</span></div><div className="bestseller-info-item"><strong>{selected.stock === null ? '—' : selected.stock}</strong><span>In stock</span></div><div className="bestseller-info-item"><strong>{selected.vendor}</strong><span>Vendor</span></div></div><div className="btn-row"><Button to={`/books/${selected.id}`} variant="secondary">View Book <ArrowRight size={15} /></Button><Button onClick={() => addToCart(selected.id)} variant="ghost">Add to Cart <ShoppingBag size={14} /></Button></div></div><div className="bestseller-stage" aria-live="polite"><div className="stage-glow" /><div className="stage-layer three" /><div className="stage-layer one" /><div className="stage-layer two" /><div className="stage-cover" data-title={selected.title}><img src={selected.cover || FEATURED_IMAGE} alt={`${selected.title} cover`} /><span aria-hidden="true" /></div></div></div><div className="container bestseller-selector">{bestsellers.map((book, index) => <button className={`selector-item ${book.id === selected.id ? 'selected' : ''}`} key={book.id} onClick={() => setSelectedId(book.id)} aria-label={`Select ${book.title}`}><div className="selector-thumb"><img src={book.cover || FEATURED_IMAGE} alt="" /></div><span className="index">0{index + 1}</span><strong>{book.title}</strong><span>{book.author}</span></button>)}</div></section><section className="bestseller-after"><div className="container bestseller-after-grid"><div><Chapter>Why this shelf</Chapter><h3>Selection should feel like a small discovery.</h3></div><div><p>We keep the commerce useful — price, stock, vendor and ratings are all close at hand — but the experience gives each book the breathing room of a page in a magazine.</p><Button to="/books" variant="dark">Browse every book <ArrowRight size={15} /></Button></div></div></section></div></Layout>
}

function BooksPage() {
  const [params, setParams] = useSearchParams()
  const [query, setQuery] = useState(params.get('q') || '')
  const [sort, setSort] = useState('Bestseller')
  const [category, setCategory] = useState('All')
  const [showFilters, setShowFilters] = useState(false)
  useEffect(() => {
    if ((params.get('q') || '') !== query) setParams(query ? { q: query } : {}, { replace: true })
  }, [params, query, setParams])
  const filtered = useMemo(() => {
    const value = query.toLowerCase()
    const next = books.filter((book) => (!value || [book.title, book.author, book.category, book.publisher || ''].join(' ').toLowerCase().includes(value)) && (category === 'All' || book.category === category))
    if (sort === 'Price Low → High') return [...next].sort((a, b) => (a.price ?? 99999) - (b.price ?? 99999))
    if (sort === 'Price High → Low') return [...next].sort((a, b) => (b.price ?? 0) - (a.price ?? 0))
    if (sort === 'Rating') return [...next].sort((a, b) => (b.rating ?? 0) - (a.rating ?? 0))
    if (sort === 'Newest') return [...next].sort((a, b) => (b.year ?? 0) - (a.year ?? 0))
    return next
  }, [query, sort, category])
  return <Layout><PageHero label="MarketHub / Books" title="A practical shelf for every kind of reader."><div className="search-bar"><Search size={17} color="var(--gold)" /><input className="search-input" placeholder="Search by title, author, ISBN, publisher…" value={query} onChange={(event) => setQuery(event.target.value)} /></div></PageHero><section className="container"><div className="filter-mobile-row"><Button variant="ghost" onClick={() => setShowFilters((value) => !value)}><ChevronDown size={14} /> Filters</Button><Button variant="ghost" onClick={() => document.getElementById('sort')?.focus()}><ArrowDownRight size={14} /> Sort</Button></div><div className="shop-layout"><aside className={`filter-panel ${showFilters ? 'show-mobile' : ''}`}><div className="filter-group"><h4>Category</h4>{['All', ...categories.slice(0, 6)].map((item) => <label className="filter-option" key={item}><span>{item}</span><input type="radio" checked={category === item} onChange={() => setCategory(item)} /></label>)}</div><div className="filter-group"><h4>Availability</h4><label className="filter-option"><span>In stock</span><input type="checkbox" defaultChecked /></label><label className="filter-option"><span>All titles</span><input type="checkbox" /></label></div><div className="filter-group"><h4>Format</h4><label className="filter-option"><span>Paperback</span><input type="checkbox" /></label><label className="filter-option"><span>Hardcover</span><input type="checkbox" /></label></div><Button variant="ghost" onClick={() => { setQuery(''); setCategory('All'); setSort('Bestseller') }}>Reset filters</Button></aside><div className="shop-main"><div className="shop-toolbar"><div><strong>All books</strong><span style={{ marginLeft: 10 }}>{filtered.length} titles in this view</span></div><select id="sort" className="sort-select" value={sort} onChange={(event) => setSort(event.target.value)}><option>Bestseller</option><option>Newest</option><option>Rating</option><option>Price Low → High</option><option>Price High → Low</option></select></div><BookGrid items={filtered} /></div></div></section></Layout>
}

function BookDetailsPage() {
  const { id } = useParams(); const book = getBook(id); const { wishlist, toggleWishlist, addToCart } = useMarket(); const [tab, setTab] = useState('Description'); const wished = wishlist.includes(book.id)
  const tabs = ['Description', 'Book Information', 'Reviews', 'Shipping', 'Vendor']
  return <Layout><section className="container detail-layout"><div className="detail-gallery"><div className="detail-cover" data-title={book.title}><img src={book.cover || FEATURED_IMAGE} alt={`${book.title} cover`} /></div><div className="chapter-label" style={{ marginTop: 20 }}>MarketHub / Book detail</div></div><div className="detail-copy"><span className="eyebrow">{book.category}</span><h1>{book.title}</h1><span className="author">{book.author}</span><div style={{ marginTop: 20 }}><Rating book={book} /></div><p>{book.description}</p><div className="detail-price-row"><span className="price">{money(book.price)}</span>{book.mrp && <span className="mrp">{money(book.mrp)}</span>}{discount(book) && <span className="discount">{discount(book)}% off</span>}</div><div className="meta-row" style={{ maxWidth: 520, marginBottom: 24 }}><span>Sold by <strong style={{ color: 'var(--paper)' }}>{book.vendor}</strong></span><span className={`stock ${book.stock === null ? 'out' : ''}`}>{book.stock === null ? 'Stock unavailable' : `${book.stock} available`}</span></div><div className="btn-row"><Button onClick={() => addToCart(book.id)} variant="primary">Add to Cart <ShoppingBag size={14} /></Button><Button onClick={() => addToCart(book.id)} variant="ghost">Buy Now</Button><button className="icon-button" aria-label={wished ? 'Remove from wishlist' : 'Add to wishlist'} onClick={() => toggleWishlist(book.id)}><Heart size={18} fill={wished ? 'currentColor' : 'none'} color={wished ? 'var(--gold)' : undefined} /></button></div><div className="detail-tabs"><div className="tab-list">{tabs.map((item) => <button className={`tab ${tab === item ? 'active' : ''}`} key={item} onClick={() => setTab(item)}>{item}</button>)}</div><div className="tab-panel">{tab === 'Description' && <p>{book.description} {book.title} is part of MarketHub’s local demonstration catalogue, with the product structure ready for a future connected book service.</p>}{tab === 'Book Information' && <dl className="info-list"><div><dt>ISBN</dt><dd>{safe(book.isbn)}</dd></div><div><dt>Publisher</dt><dd>{safe(book.publisher)}</dd></div><div><dt>Edition</dt><dd>{safe(book.year ? `${book.year} edition` : null)}</dd></div><div><dt>Pages</dt><dd>{safe(book.pages)}</dd></div><div><dt>Language</dt><dd>{safe(book.language)}</dd></div><div><dt>Format</dt><dd>{safe(book.format)}</dd></div><div><dt>Publication year</dt><dd>{safe(book.year)}</dd></div><div><dt>Vendor</dt><dd>{book.vendor}</dd></div></dl>}{tab === 'Reviews' && <p>{book.reviews ? `${book.reviews.toLocaleString('en-IN')} readers have left a signal for this title. Reviews are represented as local mock data in this UI phase.` : 'Information unavailable'}</p>}{tab === 'Shipping' && <p>Free delivery over ₹699. Orders are simulated in this UI phase and do not create a real shipment.</p>}{tab === 'Vendor' && <p><strong style={{ color: 'var(--paper)' }}>{book.vendor}</strong> is one of the independent booksellers represented in the MarketHub demo. <Link className="button-text" to={`/vendors/${slug(book.vendor)}`}>Visit the store <ArrowRight size={12} /></Link></p>}</div></div></div></section></Layout>
}

function SearchPage() {
  const [params, setParams] = useSearchParams(); const [query, setQuery] = useState(params.get('q') || '')
  useEffect(() => {
    if ((params.get('q') || '') !== query) setParams(query ? { q: query } : {}, { replace: true })
  }, [params, query, setParams])
  const results = books.filter((book) => !query || [book.title, book.author, book.category, book.publisher || '', book.isbn || ''].join(' ').toLowerCase().includes(query.toLowerCase()))
  const submit = (event: FormEvent) => { event.preventDefault(); setParams(query ? { q: query } : {}) }
  return <Layout><PageHero label="MarketHub / Search" title={query ? `Results for “${query}”` : 'Search the whole shelf.'}><form className="search-bar" onSubmit={submit}><Search size={17} color="var(--gold)" /><input autoFocus className="search-input" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Try Amish, fantasy, Agatha Christie…" /><Button type="submit" variant="primary">Search</Button></form><div className="suggestion-row"><button className="suggestion" onClick={() => { setQuery('Amish'); setParams({ q: 'Amish' }) }}>Amish</button><button className="suggestion" onClick={() => { setQuery('fantasy'); setParams({ q: 'fantasy' }) }}>Fantasy</button><button className="suggestion" onClick={() => { setQuery('Agatha Christie'); setParams({ q: 'Agatha Christie' }) }}>Agatha Christie</button></div></PageHero><section className="container section" style={{ paddingTop: 10 }}><div className="section-heading"><div><Chapter>Search / {results.length} matches</Chapter><h2>{results.length ? 'A few good places to begin.' : 'Nothing on this shelf yet.'}</h2></div></div><BookGrid items={results} /></section></Layout>
}

function CategoryPage() {
  const { category = '' } = useParams(); const decoded = category.replace(/-/g, ' '); const actual = categories.find((item) => item.toLowerCase() === decoded.toLowerCase()) || decoded; const results = books.filter((book) => book.category.toLowerCase() === actual.toLowerCase() || book.subcategory.toLowerCase().includes(decoded.toLowerCase()))
  return <Layout><PageHero label={`MarketHub / Category / ${actual}`} title={actual}><p>{results.length ? `${results.length} titles gathered for this shelf.` : 'Explore the catalogue by choosing another category.'}</p></PageHero><section className="container section" style={{ paddingTop: 20 }}><BookGrid items={results.length ? results : books.filter((book) => book.category.includes('Fiction')).slice(0, 6)} /></section></Layout>
}

function AuthorsPage() {
  const authors = Array.from(new Set(books.map((book) => book.author)))
  return <Layout><PageHero label="MarketHub / Authors" title="Follow the voices behind the books."><p>A considered index of the writers shaping this demo catalogue. No invented biographies, just the books.</p></PageHero><section className="container section" style={{ paddingTop: 20 }}><div className="author-grid">{authors.map((author) => { const authorBooks = books.filter((book) => book.author === author); return <Link className="author-card" to={`/authors/${slug(author)}`} key={author}><div><span className="eyebrow">{authorBooks[0].category}</span><h3>{author}</h3><p>{authorBooks.length} book{authorBooks.length !== 1 ? 's' : ''} in the catalogue</p></div><div className="author-card-footer"><span>{authorBooks[0].title}</span><ArrowUpRight size={14} color="var(--gold)" /></div></Link> })}</div></section></Layout>
}

function AuthorPage() {
  const { author = '' } = useParams(); const actual = books.find((book) => slug(book.author) === author)?.author || author.replace(/-/g, ' '); const authorBooks = books.filter((book) => book.author.toLowerCase() === actual.toLowerCase())
  return <Layout><PageHero label="MarketHub / Author" title={actual}><p>{authorBooks.length} book{authorBooks.length !== 1 ? 's' : ''} in the MarketHub catalogue.</p></PageHero><section className="container section" style={{ paddingTop: 20 }}><BookGrid items={authorBooks} /></section></Layout>
}

function VendorsPage() {
  const rankedVendors = [...sellerProfiles].sort((a, b) => getSellerScore(b) - getSellerScore(a))
  return <Layout><PageHero label="MarketHub / Vendors" title="Meet the booksellers."><p>Many vendors, one trusted reading room. Explore booksellers ranked by their local Seller Score.</p></PageHero><section className="container section" style={{ paddingTop: 20 }}><div className="vendor-grid">{rankedVendors.map((vendor, index) => { const vendorBooks = books.filter((book) => book.vendor === vendor.name); return <article className="vendor-card" key={vendor.name}><Link to={`/vendors/${slug(vendor.name)}`}><div><span className="eyebrow">Seller Score · {getSellerScore(vendor)}/100</span><h3>{vendor.name}</h3><p>{vendorBooks.length} books · {vendor.city} · Verified</p></div><div className="vendor-card-footer"><span>{vendorBooks[0]?.category || 'Curated books'}</span><ArrowUpRight size={14} color="var(--gold)" /></div></Link><SellerRankingDisclosure name={vendor.name} /></article> })}</div></section></Layout>
}

function VendorPage() {
  const { id = '' } = useParams(); const actual = vendorNames.find((vendor) => slug(vendor) === id) || id.replace(/-/g, ' '); const vendorBooks = books.filter((book) => book.vendor.toLowerCase() === actual.toLowerCase())
  return <Layout><PageHero label="MarketHub / Vendor" title={actual}><p>Independent bookseller · {vendorBooks.length} titles in this demo store</p></PageHero><section className="container section vendor-detail-section" style={{ paddingTop: 20 }}><SellerPassport name={actual} /><div className="section-heading"><div><Chapter>Store shelf</Chapter><h2>Books from this vendor.</h2></div><Button to="/vendors" variant="ghost"><ArrowLeft size={14} /> All vendors</Button></div><BookGrid items={vendorBooks.length ? vendorBooks : books.slice(0, 4)} /></section></Layout>
}

function AuthPage({ kind }: { kind: 'login' | 'register' | 'vendor' }) {
  const { setDemoUser, showToast } = useMarket(); const navigate = useNavigate(); const isVendor = kind === 'vendor'; const isRegister = kind === 'register';
  const title = isVendor ? 'Start selling books.' : isRegister ? 'Make room for more stories.' : 'Your reading room, wherever you are.'
  const submit = (event: FormEvent) => { event.preventDefault(); if (!isVendor) setDemoUser(true); showToast(isVendor ? 'Vendor application saved as a demo' : isRegister ? 'Welcome to MarketHub' : 'Signed in as Demo User'); navigate(isVendor ? '/vendor' : '/customer') }
  return <div className="auth-page"><div className="auth-visual"><Link to="/"><Brand /></Link><div><h1>{title}</h1><p>{isVendor ? 'Join a considered marketplace built for booksellers who care about the titles they put into the world.' : 'Save the titles you mean to read, track every order, and keep your next chapter close.'}</p></div></div><div className="auth-panel"><form className="auth-form" onSubmit={submit}><Chapter>{isVendor ? 'MarketHub / Vendor registration' : isRegister ? 'MarketHub / Create account' : 'MarketHub / Sign in'}</Chapter><h2>{isVendor ? 'Your store begins here.' : isRegister ? 'Create an account.' : 'Welcome back.'}</h2><p>{isVendor ? 'Tell us a little about your bookstore.' : isRegister ? 'The shelf gets better when it remembers you.' : 'Continue with your demo account to explore the full experience.'}</p>{isVendor ? <><div className="field"><label htmlFor="store">Store name</label><input id="store" placeholder="The Reading Room" required /></div><div className="field"><label htmlFor="owner">Owner name</label><input id="owner" placeholder="Your name" required /></div><div className="field"><label htmlFor="phone">Phone</label><input id="phone" placeholder="+91 98765 43210" required /></div><div className="field"><label htmlFor="vendor-email">Email</label><input id="vendor-email" type="email" placeholder="hello@yourstore.com" required /></div><div className="field"><label htmlFor="description">Store description</label><textarea id="description" placeholder="What makes your shelf special?" /></div></> : <><div className="field"><label htmlFor="email">Email</label><input id="email" type="email" placeholder="you@example.com" required defaultValue={isRegister ? '' : 'reader@markethub.demo'} /></div><div className="field"><label htmlFor="password">Password</label><input id="password" type="password" placeholder="••••••••" required defaultValue={isRegister ? '' : 'password'} /></div>{isRegister && <><div className="field"><label htmlFor="name">Full name</label><input id="name" placeholder="Your full name" required /></div><div className="field"><label htmlFor="confirm">Confirm password</label><input id="confirm" type="password" placeholder="••••••••" required /></div></>}</>}<Button type="submit" variant="primary">{isVendor ? 'Start Selling Books' : isRegister ? 'Create Account' : 'Sign In'} <ArrowRight size={14} /></Button>{!isVendor && !isRegister && <Button type="button" variant="dark" onClick={() => { setDemoUser(true); showToast('Signed in as Demo User'); navigate('/customer') }}>Continue as Demo User</Button>}<div className="auth-links">{!isVendor && <Link to={isRegister ? '/login' : '/register'}>{isRegister ? 'Already a member?' : 'Create account'}</Link>}<Link to={isVendor ? '/login' : '/vendor/register'}>{isVendor ? 'Customer sign in' : 'Become a Vendor'}</Link></div></form></div></div>
}

const orderStatus = ['Pending', 'Confirmed', 'Packed', 'Shipped', 'Delivered']
function OrderTimeline({ status = 'Shipped' }: { status?: string }) { const active = orderStatus.indexOf(status); return <div className="order-timeline">{orderStatus.map((item, index) => <div className={`timeline-step ${index <= active ? 'done' : ''}`} key={item}><span>{index <= active ? <Check size={12} /> : index + 1}</span><div><strong>{item}</strong><small>{index <= active ? index === active ? 'Current status' : 'Complete' : 'Upcoming'}</small></div></div>)}</div> }

function CustomerNav() { return <nav className="side-nav"><NavLink to="/customer"><LayoutDashboard size={14} /> Overview</NavLink><NavLink to="/customer/orders"><Package size={14} /> Orders</NavLink><NavLink to="/customer/wishlist"><Heart size={14} /> Wishlist</NavLink><NavLink to="/customer/profile"><UserRound size={14} /> Profile</NavLink></nav> }
function DashboardShell({ title, children, sidebar = 'customer' }: { title: string; children: ReactNode; sidebar?: 'customer' | 'vendor' | 'admin' }) {
  const nav = sidebar === 'customer' ? <CustomerNav /> : sidebar === 'vendor' ? <VendorNav /> : <AdminNav />
  return <Layout><div className="dashboard-layout"><aside className="dashboard-sidebar"><Brand /><h2>{title}</h2>{nav}<Button to="/" variant="ghost">Back to shop <ArrowLeft size={13} /></Button></aside><section className="dashboard-content">{children}</section></div></Layout>
}

function CustomerDashboard() {
  return <DashboardShell title="Your shelf"><Chapter>Customer / Overview</Chapter><h1>Good morning, reader.</h1><div className="metrics-grid"><div className="metric-card"><span>Total orders</span><strong>08</strong></div><div className="metric-card"><span>Active orders</span><strong>02</strong></div><div className="metric-card"><span>Wishlist</span><strong>12</strong></div><div className="metric-card"><span>Total spent</span><strong>₹8.4k</strong></div></div><div className="dashboard-grid"><div className="panel"><div className="panel-heading"><h2>Recent orders</h2><Link className="button-text" to="/customer/orders">View all <ArrowRight size={12} /></Link></div><div className="table-wrap"><table className="data-table"><thead><tr><th>Order</th><th>Book</th><th>Status</th><th>Total</th></tr></thead><tbody>{orderRows.slice(0, 3).map((order) => <tr key={order.id}><td>{order.id}</td><td>{order.item}</td><td><Status tone={order.status === 'Shipped' ? 'normal' : 'pending'}>{order.status}</Status></td><td>{order.total}</td></tr>)}</tbody></table></div></div><div className="panel"><div className="panel-heading"><h2>Recommended</h2><Sparkles size={17} color="var(--gold)" /></div><Link to={`/books/${books[5].id}`} className="mini-recommendation"><CoverArt book={books[5]} showTitle={false} /><div><strong>{books[5].title}</strong><span>{books[5].author}</span><Rating book={books[5]} /></div></Link><Link to={`/books/${books[1].id}`} className="mini-recommendation"><CoverArt book={books[1]} showTitle={false} /><div><strong>{books[1].title}</strong><span>{books[1].author}</span><Rating book={books[1]} /></div></Link></div></div></DashboardShell>
}

function CartPage() {
  const { cart, cartItems, updateQuantity, removeFromCart, toggleWishlist } = useMarket(); const subtotal = cartItems.reduce((sum, book) => sum + (book.price || 0) * (cart[book.id] || 0), 0); const delivery = subtotal >= 699 || subtotal === 0 ? 0 : 49; const total = subtotal + delivery
  return <Layout><PageHero label="MarketHub / Customer / Cart" title="Your reading list, gathered."><p>{Object.values(cart).reduce((a, b) => a + b, 0)} item{Object.values(cart).reduce((a, b) => a + b, 0) !== 1 ? 's' : ''} ready for the next chapter.</p></PageHero><section className="container cart-layout"><div className="cart-items">{cartItems.length ? cartItems.map((book) => <div className="cart-item" key={book.id}><Link className="cart-item-cover" to={`/books/${book.id}`}><img src={book.cover || FEATURED_IMAGE} alt={`${book.title} cover`} /></Link><div><Link to={`/books/${book.id}`}><h3>{book.title}</h3></Link><p>{book.author} · {book.vendor}</p><div className="quantity-control"><button aria-label="Decrease quantity" onClick={() => updateQuantity(book.id, (cart[book.id] || 1) - 1)}><Minus size={12} /></button><span>{cart[book.id]}</span><button aria-label="Increase quantity" onClick={() => updateQuantity(book.id, (cart[book.id] || 0) + 1)}><Plus size={12} /></button></div></div><div className="cart-item-side"><strong>{money(book.price)}</strong><div><button className="button-text" onClick={() => toggleWishlist(book.id)}><Heart size={12} /> Save</button><button className="button-text" style={{ marginLeft: 12 }} onClick={() => removeFromCart(book.id)}><Trash2 size={12} /> Remove</button></div></div></div>) : <div className="empty-state"><h2>Your cart is waiting.</h2><p>Start with a title from the shelf and we’ll keep it here.</p><Button to="/books">Explore Books <ArrowRight size={14} /></Button></div>}</div><aside className="summary-card"><h2>Order summary</h2><div className="summary-line"><span>Subtotal</span><strong>{money(subtotal)}</strong></div><div className="summary-line"><span>Delivery</span><strong>{delivery ? money(delivery) : 'Free'}</strong></div><div className="summary-line"><span>Discount</span><strong>—</strong></div><div className="summary-line total"><span>Total</span><strong>{money(total)}</strong></div><Button to={cartItems.length ? '/customer/checkout' : '/books'} variant="primary" disabled={!cartItems.length}>Proceed to Checkout <ArrowRight size={14} /></Button><p className="paper-muted" style={{ fontSize: 10, lineHeight: 1.6 }}>This is a simulated checkout. No payment will be processed.</p></aside></section></Layout>
}

function CheckoutPage() {
  const { cartItems, cart, clearCart, showToast } = useMarket(); const navigate = useNavigate(); const [step, setStep] = useState(1); const [payment, setPayment] = useState('UPI'); const [confirmed, setConfirmed] = useState(false); const [placedOrder, setPlacedOrder] = useState<{ id: string; items: number; total: number } | null>(null); const total = cartItems.reduce((sum, book) => sum + (book.price || 0) * (cart[book.id] || 0), 0)
  const confirm = () => { setPlacedOrder({ id: `MH-${Date.now().toString().slice(-5)}`, items: cartItems.length, total }); setConfirmed(true); clearCart(); showToast('Order confirmed') }
  if (confirmed && placedOrder) return <Layout><section className="container section"><div className="confirmation"><Chapter>MarketHub / Order confirmed</Chapter><h1>It’s on its way.</h1><p>Your demo order <strong>{placedOrder.id}</strong> has been placed. Estimated delivery: 3–5 working days.</p><div className="summary-line"><span>Items</span><strong>{placedOrder.items} title{placedOrder.items === 1 ? '' : 's'}</strong></div><div className="summary-line total"><span>Total</span><strong>{money(placedOrder.total)}</strong></div><Button to="/customer/orders" variant="dark">View Orders <ArrowRight size={14} /></Button></div><BookLifecycleStrip status="Shipped" /></section></Layout>
  return <Layout><PageHero label="MarketHub / Customer / Checkout" title="A few details, then your next chapter."><p>Simulated checkout — no real payment processing or account changes.</p></PageHero><section className="container checkout-shell"><div className="checkout-steps">{['Address', 'Delivery', 'Payment', 'Review'].map((item, index) => <div className={`checkout-step ${step >= index + 1 ? 'active' : ''}`} key={item}><strong>0{index + 1}</strong>{item}</div>)}</div><div className="checkout-card">{step === 1 && <><h2>Where should we send it?</h2><div className="form-grid"><div className="field"><label htmlFor="full-name">Full name</label><input id="full-name" placeholder="Aarav Mehta" defaultValue="Aarav Mehta" /></div><div className="field"><label htmlFor="phone-number">Phone</label><input id="phone-number" placeholder="+91 98765 43210" /></div><div className="field span-2"><label htmlFor="address">Address</label><textarea id="address" placeholder="House, street, city, state, pin code" /></div></div><Button onClick={() => setStep(2)} variant="primary">Continue to delivery <ArrowRight size={14} /></Button></>}{step === 2 && <><h2>Choose delivery.</h2><div className="payment-options"><button className="payment-option selected"><Truck size={18} /><strong style={{ display: 'block', marginTop: 13 }}>Standard</strong><span style={{ display: 'block', marginTop: 5, fontSize: 10 }}>3–5 working days · Free</span></button><button className="payment-option"><Zap size={18} /><strong style={{ display: 'block', marginTop: 13 }}>Priority</strong><span style={{ display: 'block', marginTop: 5, fontSize: 10 }}>1–2 working days · ₹99</span></button></div><div className="btn-row" style={{ marginTop: 25 }}><Button onClick={() => setStep(1)} variant="ghost"><ArrowLeft size={14} /> Back</Button><Button onClick={() => setStep(3)} variant="primary">Continue to payment <ArrowRight size={14} /></Button></div></>}{step === 3 && <><h2>How would you like to pay?</h2><div className="payment-options">{['UPI', 'Card', 'Cash on Delivery'].map((item) => <button className={`payment-option ${payment === item ? 'selected' : ''}`} key={item} onClick={() => setPayment(item)}><strong>{item}</strong><span style={{ display: 'block', marginTop: 6, fontSize: 10 }}>{item === 'Cash on Delivery' ? 'Pay when it arrives' : 'Demo payment option'}</span></button>)}</div><div className="btn-row" style={{ marginTop: 25 }}><Button onClick={() => setStep(2)} variant="ghost"><ArrowLeft size={14} /> Back</Button><Button onClick={() => setStep(4)} variant="primary">Review order <ArrowRight size={14} /></Button></div></>}{step === 4 && <><h2>Review your order.</h2><div className="summary-line"><span>Items</span><strong>{cartItems.length} titles</strong></div><div className="summary-line"><span>Payment</span><strong>{payment}</strong></div><div className="summary-line total"><span>Total</span><strong>{money(total)}</strong></div><div className="btn-row" style={{ marginTop: 25 }}><Button onClick={() => setStep(3)} variant="ghost"><ArrowLeft size={14} /> Back</Button><Button onClick={confirm} variant="primary">Confirm order <Check size={14} /></Button></div></>}</div></section></Layout>
}

function OrdersPage() { return <DashboardShell title="Your orders"><Chapter>Customer / Orders</Chapter><h1>Keep an eye on the next delivery.</h1><div className="panel"><div className="table-wrap"><table className="data-table"><thead><tr><th>Order</th><th>Item</th><th>Status</th><th>Total</th><th>View</th></tr></thead><tbody>{orderRows.map((order) => <tr key={order.id}><td>{order.id}</td><td>{order.item}</td><td><Status tone={order.status === 'Pending' ? 'pending' : 'normal'}>{order.status}</Status></td><td>{order.total}</td><td><Link className="button-text" to={`/customer/orders/${order.id}`}>Details <ArrowRight size={12} /></Link></td></tr>)}</tbody></table></div></div></DashboardShell> }
function OrderDetailsPage() { const { id } = useParams(); const order = orderRows.find((item) => item.id === id) || orderRows[0]; return <DashboardShell title="Order detail"><Chapter>Customer / Order / {order.id}</Chapter><h1>{order.item}</h1><div className="dashboard-grid"><div className="panel"><h2>Order timeline</h2><OrderTimeline status={order.status} /></div><div className="panel"><h2>Order summary</h2><div className="summary-line"><span>Order ID</span><strong>{order.id}</strong></div><div className="summary-line"><span>Vendor</span><strong>Chapter One Books</strong></div><div className="summary-line total"><span>Total</span><strong>{order.total}</strong></div></div></div></DashboardShell> }
function WishlistPage() { const { wishlist } = useMarket(); const items = books.filter((book) => wishlist.includes(book.id)); return <DashboardShell title="Your shelf"><Chapter>Customer / Wishlist</Chapter><h1>Books you want to remember.</h1>{items.length ? <BookGrid items={items} /> : <div className="empty-state"><h2>Your bookshelf is waiting.</h2><p>Save the titles that make you pause. They’ll stay here until you’re ready.</p><Button to="/books">Explore Books <ArrowRight size={14} /></Button></div>}</DashboardShell> }
function ProfilePage() { const { showToast } = useMarket(); return <DashboardShell title="Your profile"><Chapter>Customer / Profile</Chapter><h1>A few details about you.</h1><div className="panel" style={{ maxWidth: 720 }}><div className="form-grid"><div className="field"><label htmlFor="profile-name">Full name</label><input id="profile-name" defaultValue="Aarav Mehta" /></div><div className="field"><label htmlFor="profile-email">Email</label><input id="profile-email" defaultValue="reader@markethub.demo" /></div><div className="field span-2"><label htmlFor="profile-note">Reading note</label><textarea id="profile-note" defaultValue="Looking for stories with a little atmosphere." /></div></div><Button onClick={() => showToast('Profile saved')}>Save changes <Check size={14} /></Button></div></DashboardShell> }

function VendorNav() { return <nav className="side-nav"><NavLink to="/vendor"><LayoutDashboard size={14} /> Overview</NavLink><NavLink to="/vendor/books"><BookOpen size={14} /> Books</NavLink><NavLink to="/vendor/books/new"><Plus size={14} /> Add book</NavLink><NavLink to="/vendor/orders"><Package size={14} /> Orders</NavLink><NavLink to="/vendor/analytics"><TrendingUp size={14} /> Analytics</NavLink><NavLink to="/vendor/profile"><Store size={14} /> Profile</NavLink></nav> }
function AdminNav() { return <nav className="side-nav"><NavLink to="/admin"><LayoutDashboard size={14} /> Overview</NavLink><NavLink to="/admin/users"><Users size={14} /> Users</NavLink><NavLink to="/admin/vendors"><Store size={14} /> Vendors</NavLink><NavLink to="/admin/books"><BookOpen size={14} /> Books</NavLink><NavLink to="/admin/orders"><Package size={14} /> Orders</NavLink><NavLink to="/admin/analytics"><TrendingUp size={14} /> Analytics</NavLink><NavLink to="/admin/settings"><Settings size={14} /> Settings</NavLink></nav> }

function SimpleMetrics({ items }: { items: [string, string][] }) { return <div className="metrics-grid">{items.map(([label, value]) => <div className="metric-card" key={label}><span>{label}</span><strong>{value}</strong></div>)}</div> }
function Chart({ kind = 'area' }: { kind?: 'area' | 'bar' | 'line' }) { return <div className="chart-box"> <ResponsiveContainer width="100%" height="100%">{kind === 'bar' ? <BarChart data={chartData}><CartesianGrid stroke="rgba(244,239,229,.1)" vertical={false} /><XAxis dataKey="month" stroke="#8c877f" fontSize={10} tickLine={false} axisLine={false} /><YAxis stroke="#8c877f" fontSize={10} tickLine={false} axisLine={false} /><Tooltip contentStyle={{ background: '#151517', border: '1px solid rgba(244,239,229,.16)', color: '#f4efe5', fontSize: 11 }} /><Bar dataKey="orders" fill="#c3a47b" radius={[2, 2, 0, 0]} /></BarChart> : kind === 'line' ? <LineChart data={chartData}><CartesianGrid stroke="rgba(244,239,229,.1)" vertical={false} /><XAxis dataKey="month" stroke="#8c877f" fontSize={10} tickLine={false} axisLine={false} /><YAxis stroke="#8c877f" fontSize={10} tickLine={false} axisLine={false} /><Tooltip contentStyle={{ background: '#151517', border: '1px solid rgba(244,239,229,.16)', color: '#f4efe5', fontSize: 11 }} /><Line type="monotone" dataKey="orders" stroke="#c3a47b" strokeWidth={2} dot={false} /></LineChart> : <AreaChart data={chartData}><defs><linearGradient id="revenueFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#c3a47b" stopOpacity=".38" /><stop offset="100%" stopColor="#c3a47b" stopOpacity="0" /></linearGradient></defs><CartesianGrid stroke="rgba(244,239,229,.1)" vertical={false} /><XAxis dataKey="month" stroke="#8c877f" fontSize={10} tickLine={false} axisLine={false} /><YAxis stroke="#8c877f" fontSize={10} tickLine={false} axisLine={false} /><Tooltip contentStyle={{ background: '#151517', border: '1px solid rgba(244,239,229,.16)', color: '#f4efe5', fontSize: 11 }} /><Area type="monotone" dataKey="revenue" stroke="#c3a47b" fill="url(#revenueFill)" strokeWidth={2} /></AreaChart>}</ResponsiveContainer></div> }

function VendorDashboard() { return <DashboardShell title="Vendor studio" sidebar="vendor"><Chapter>Vendor / Overview</Chapter><h1>Good morning, bookseller.</h1><SimpleMetrics items={[["Sales", '₹68.4k'], ['Orders', '124'], ['Books', '55'], ['Low stock', '07']]} /><div className="dashboard-grid"><div className="panel"><div className="panel-heading"><h2>Sales overview</h2><span className="muted">Last 6 months</span></div><Chart /></div><div className="panel"><div className="panel-heading"><h2>Top books</h2><MoreHorizontal size={17} color="var(--muted)" /></div>{books.slice(0, 4).map((book, index) => <div className="summary-line" key={book.id}><span>0{index + 1} · {book.title}</span><strong>{[42, 38, 31, 24][index]} sold</strong></div>)}</div></div><div className="panel" style={{ marginTop: 18 }}><div className="panel-heading"><h2>Inventory pulse</h2><Link className="button-text" to="/vendor/books">Manage inventory <ArrowRight size={12} /></Link></div><div className="bar-chart-box"><Chart kind="bar" /></div></div></DashboardShell> }

function VendorBooks() { return <DashboardShell title="Vendor studio" sidebar="vendor"><Chapter>Vendor / Books</Chapter><div className="panel-heading"><h1 style={{ margin: 0 }}>Your book inventory.</h1><Button to="/vendor/books/new" variant="primary"><Plus size={14} /> Add book</Button></div><div className="panel"><div className="table-wrap"><table className="data-table"><thead><tr><th>Book</th><th>Author</th><th>Category</th><th>Price</th><th>Stock</th><th>Status</th><th>Actions</th></tr></thead><tbody>{books.map((book) => <tr key={book.id}><td><strong>{book.title}</strong></td><td>{book.author}</td><td>{book.category}</td><td>{money(book.price)}</td><td>{safe(book.stock)}</td><td><Status tone={book.stock === null ? 'danger' : book.stock < 8 ? 'pending' : 'normal'}>{book.stock === null ? 'Unavailable' : book.stock < 8 ? 'Low stock' : 'Active'}</Status></td><td><Link className="button-text" to={`/vendor/books/${book.id}/edit`}>Edit <ArrowRight size={12} /></Link></td></tr>)}</tbody></table></div></div></DashboardShell> }

function VendorBookEditor() { const { id } = useParams(); const book = getBook(id); const { showToast } = useMarket(); const editing = Boolean(id); return <DashboardShell title="Vendor studio" sidebar="vendor"><Chapter>Vendor / {editing ? 'Edit book' : 'Add book'}</Chapter><h1>{editing ? `Edit ${book.title}.` : 'Add a new title.'}</h1><div className="panel" style={{ maxWidth: 900 }}><div className="form-grid"><div className="field"><label>Title</label><input defaultValue={editing ? book.title : ''} placeholder="Book title" /></div><div className="field"><label>Author</label><input defaultValue={editing ? book.author : ''} placeholder="Author name" /></div><div className="field"><label>Category</label><select defaultValue={editing ? book.category : categories[0]}>{categories.map((item) => <option key={item}>{item}</option>)}</select></div><div className="field"><label>Subcategory</label><input defaultValue={editing ? book.subcategory : ''} placeholder="Subcategory" /></div><div className="field"><label>ISBN</label><input defaultValue={editing ? (book.isbn || '') : ''} placeholder="ISBN or leave blank" /></div><div className="field"><label>Publisher</label><input defaultValue={editing ? (book.publisher || '') : ''} placeholder="Publisher" /></div><div className="field"><label>Edition</label><input defaultValue={editing ? (book.year || '') : ''} placeholder="Publication year" /></div><div className="field"><label>Pages</label><input defaultValue={editing ? (book.pages || '') : ''} placeholder="Page count" /></div><div className="field"><label>Language</label><input defaultValue={editing ? (book.language || '') : ''} placeholder="English" /></div><div className="field"><label>Format</label><input defaultValue={editing ? (book.format || '') : ''} placeholder="Paperback" /></div><div className="field span-2"><label>Description</label><textarea defaultValue={editing ? book.description : ''} placeholder="What should a reader know?" /></div><div className="field"><label>MRP</label><input type="number" defaultValue={editing ? (book.mrp || '') : ''} placeholder="599" /></div><div className="field"><label>Selling price</label><input type="number" defaultValue={editing ? (book.price || '') : ''} placeholder="399" /></div><div className="field"><label>Stock</label><input type="number" defaultValue={editing ? (book.stock || '') : ''} placeholder="20" /></div><div className="field"><label>Cover image</label><input defaultValue={editing ? (book.cover || '') : ''} placeholder="Image URL" /></div></div><Button onClick={() => showToast(editing ? 'Book changes saved' : 'Book added to inventory')}>{editing ? 'Save changes' : 'Add book'} <Check size={14} /></Button></div></DashboardShell> }

function VendorOrders() { return <DashboardShell title="Vendor studio" sidebar="vendor"><Chapter>Vendor / Orders</Chapter><h1>Orders to keep moving.</h1><div className="panel"><div className="table-wrap"><table className="data-table"><thead><tr><th>Order</th><th>Customer</th><th>Book</th><th>Status</th><th>Total</th><th>View</th></tr></thead><tbody>{orderRows.map((order) => <tr key={order.id}><td>{order.id}</td><td>{order.customer}</td><td>{order.item}</td><td><Status>{order.status}</Status></td><td>{order.total}</td><td><Link className="button-text" to={`/vendor/orders/${order.id}`}>Open <ArrowRight size={12} /></Link></td></tr>)}</tbody></table></div></div></DashboardShell> }
function VendorOrderDetails() { const { id } = useParams(); const order = orderRows.find((item) => item.id === id) || orderRows[0]; return <DashboardShell title="Vendor studio" sidebar="vendor"><Chapter>Vendor / Order / {order.id}</Chapter><h1>Prepare the next handoff.</h1><div className="dashboard-grid"><div className="panel"><h2>{order.item}</h2><p className="muted" style={{ lineHeight: 1.7 }}>Customer: {order.customer}<br />Order total: {order.total}<br />Vendor: Chapter One Books</p><Button variant="primary">Update status <ChevronDown size={14} /></Button></div><div className="panel"><h2>Timeline</h2><OrderTimeline status={order.status} /></div></div></DashboardShell> }
function VendorAnalytics() { return <DashboardShell title="Vendor studio" sidebar="vendor"><Chapter>Vendor / Analytics</Chapter><h1>Numbers with a little context.</h1><div className="dashboard-grid"><div className="panel"><div className="panel-heading"><h2>Revenue</h2><span className="muted">₹3.05L this year</span></div><Chart /></div><div className="panel"><div className="panel-heading"><h2>Orders</h2><span className="muted">124 completed</span></div><Chart kind="line" /></div></div><div className="dashboard-grid" style={{ marginTop: 18 }}><div className="panel"><div className="panel-heading"><h2>Top books</h2></div><Chart kind="bar" /></div><div className="panel"><div className="panel-heading"><h2>Inventory</h2></div><div className="summary-line"><span>Healthy stock</span><strong>43 titles</strong></div><div className="summary-line"><span>Low stock</span><strong>07 titles</strong></div><div className="summary-line"><span>Information unavailable</span><strong>05 titles</strong></div></div></div></DashboardShell> }
function VendorProfile() { const { showToast } = useMarket(); return <DashboardShell title="Vendor studio" sidebar="vendor"><Chapter>Vendor / Profile</Chapter><h1>Tell readers where you’re from.</h1><div className="panel" style={{ maxWidth: 760 }}><div className="form-grid"><div className="field"><label>Store name</label><input defaultValue="Chapter One Books" /></div><div className="field"><label>Owner name</label><input defaultValue="Aarav Mehta" /></div><div className="field"><label>Email</label><input defaultValue="hello@chapterone.demo" /></div><div className="field"><label>Phone</label><input defaultValue="+91 98765 43210" /></div><div className="field span-2"><label>Store description</label><textarea defaultValue="A considered shelf of new voices and old favourites." /></div></div><Button onClick={() => showToast('Store profile saved')}>Save profile <Check size={14} /></Button></div></DashboardShell> }

function AdminOverview() { return <DashboardShell title="Control room" sidebar="admin"><Chapter>Admin / Overview</Chapter><h1>The whole marketplace, in view.</h1><SimpleMetrics items={[["Customers", '428'], ['Vendors', '18'], ['Books', '55'], ['Orders', '1,240']]} /><div className="dashboard-grid"><div className="panel"><div className="panel-heading"><h2>Revenue</h2><span className="muted">₹6.84L</span></div><Chart /></div><div className="panel"><div className="panel-heading"><h2>Popular books</h2><TrendingUp size={17} color="var(--gold)" /></div>{books.slice(0, 4).map((book, index) => <div className="summary-line" key={book.id}><span>0{index + 1} · {book.title}</span><strong>{[824, 602, 488, 402][index]}</strong></div>)}</div></div></DashboardShell> }
function AdminCollection({ type }: { type: 'users' | 'vendors' | 'books' | 'categories' | 'orders' }) { const titles = { users: 'People who read here.', vendors: 'The booksellers.', books: 'Every title in the room.', categories: 'The shelves.', orders: 'Every handoff.' }; const heading = titles[type]; const rows = type === 'books' ? books.map((book) => [book.title, book.author, book.category, money(book.price)]) : type === 'orders' ? orderRows.map((order) => [order.id, order.customer, order.status, order.total]) : (type === 'vendors' ? vendorNames.map((name) => [name, 'Independent', '4.8', 'Active']) : type === 'categories' ? categories.map((item, index) => [item, `${index + 1} shelf`, 'Curated', 'Active']) : ['Aarav Mehta','Meera Iyer','Rohan Shah','Ishita Rao'].map((name, index) => [name, `reader${index + 1}@demo`, 'Customer', 'Active']))
  return <DashboardShell title="Control room" sidebar="admin"><Chapter>Admin / {type}</Chapter><h1>{heading}</h1><div className="panel"><div className="table-wrap"><table className="data-table"><thead><tr><th>Primary</th><th>Secondary</th><th>Type</th><th>Status</th><th>Actions</th></tr></thead><tbody>{rows.map((row, index) => <tr key={`${row[0]}-${index}`}>{row.map((cell) => <td key={cell}>{cell}</td>)}<td><button className="button-text">Review <ArrowRight size={12} /></button></td></tr>)}</tbody></table></div></div></DashboardShell> }
function AdminAnalytics() { return <DashboardShell title="Control room" sidebar="admin"><Chapter>Admin / Analytics</Chapter><h1>See where the reading is moving.</h1><div className="dashboard-grid"><div className="panel"><h2>Revenue</h2><Chart /></div><div className="panel"><h2>Orders</h2><Chart kind="bar" /></div></div><div className="dashboard-grid" style={{ marginTop: 18 }}><div className="panel"><h2>Vendor performance</h2><Chart kind="line" /></div><div className="panel"><h2>Popular books</h2><Chart kind="bar" /></div></div></DashboardShell> }
function AdminSettings() { const { showToast } = useMarket(); return <DashboardShell title="Control room" sidebar="admin"><Chapter>Admin / Settings</Chapter><h1>Keep the room considered.</h1><div className="panel" style={{ maxWidth: 760 }}><div className="field"><label>Marketplace name</label><input defaultValue="MarketHub" /></div><div className="field" style={{ marginTop: 16 }}><label>Marketplace note</label><textarea defaultValue="A premium multi-vendor bookstore for readers." /></div><Button onClick={() => showToast('Settings saved')}>Save settings <Check size={14} /></Button></div></DashboardShell> }

function App() {
  const [isLoading, setIsLoading] = useState(true)
  const [isExiting, setIsExiting] = useState(false)

  useEffect(() => {
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      setIsLoading(false)
      return
    }
    const exitTimer = window.setTimeout(() => setIsExiting(true), 650)
    const removeTimer = window.setTimeout(() => setIsLoading(false), 900)
    return () => {
      window.clearTimeout(exitTimer)
      window.clearTimeout(removeTimer)
    }
  }, [])

  return <>{isLoading && <div className={`app-loader ${isExiting ? 'is-exiting' : ''}`} role="status" aria-label="Loading MarketHub"><div className="app-loader-brand"><span className="loader-book"><BookOpen size={24} /></span><Brand /></div><div className="loader-track"><span /></div><p>Making room for stories…</p></div>}<Routes><Route path="/" element={<HomePage />} /><Route path="/books" element={<BooksPage />} /><Route path="/books/:id" element={<BookDetailsPage />} /><Route path="/search" element={<SearchPage />} /><Route path="/category/:category" element={<CategoryPage />} /><Route path="/bestsellers" element={<BestsellersPage />} /><Route path="/authors" element={<AuthorsPage />} /><Route path="/authors/:author" element={<AuthorPage />} /><Route path="/vendors" element={<VendorsPage />} /><Route path="/vendors/:id" element={<VendorPage />} /><Route path="/login" element={<AuthPage kind="login" />} /><Route path="/register" element={<AuthPage kind="register" />} /><Route path="/vendor/register" element={<AuthPage kind="vendor" />} /><Route path="/customer" element={<CustomerDashboard />} /><Route path="/customer/cart" element={<CartPage />} /><Route path="/customer/checkout" element={<CheckoutPage />} /><Route path="/customer/orders" element={<OrdersPage />} /><Route path="/customer/orders/:id" element={<OrderDetailsPage />} /><Route path="/customer/wishlist" element={<WishlistPage />} /><Route path="/customer/profile" element={<ProfilePage />} /><Route path="/vendor" element={<VendorDashboard />} /><Route path="/vendor/books" element={<VendorBooks />} /><Route path="/vendor/books/new" element={<VendorBookEditor />} /><Route path="/vendor/books/:id/edit" element={<VendorBookEditor />} /><Route path="/vendor/orders" element={<VendorOrders />} /><Route path="/vendor/orders/:id" element={<VendorOrderDetails />} /><Route path="/vendor/analytics" element={<VendorAnalytics />} /><Route path="/vendor/profile" element={<VendorProfile />} /><Route path="/admin" element={<AdminOverview />} /><Route path="/admin/users" element={<AdminCollection type="users" />} /><Route path="/admin/vendors" element={<AdminCollection type="vendors" />} /><Route path="/admin/books" element={<AdminCollection type="books" />} /><Route path="/admin/categories" element={<AdminCollection type="categories" />} /><Route path="/admin/orders" element={<AdminCollection type="orders" />} /><Route path="/admin/analytics" element={<AdminAnalytics />} /><Route path="/admin/settings" element={<AdminSettings />} /><Route path="*" element={<Navigate to="/" replace />} /></Routes></>
}

export default App
